<script lang="ts">
	import { ArrowUpRight, CalendarDays, MapPin } from '@lucide/svelte';
	type Scholarship = { provider:string; applicationStatus:'open'|'upcoming'|'closed'|'unconfirmed'; deadline:string|null; slug:string; category:string; title:string; country:string; fundingType:string };
	let { item }: { item: Scholarship } = $props();
	const dateLabel = $derived(item.deadline ? new Date(`${item.deadline}T00:00:00`).toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}) : 'Deadline not confirmed');
	const applicationLabel = $derived(({open:'Open',upcoming:'Upcoming',closed:'Closed',unconfirmed:'Unconfirmed'} as const)[item.applicationStatus]);
</script>
<article class="scholar-card"><div class="card-top"><span class="provider-mark">{item.provider.split(/\s+/).slice(0,2).map((s:string)=>s[0]).join('').toUpperCase()}</span><span class="status-pill {item.applicationStatus==='open'?'status-open':item.applicationStatus==='upcoming'?'status-upcoming':'status-closed'}">{applicationLabel}</span></div><div class="card-copy"><span class="card-category">{item.category} · Verified</span><h3><a href="/scholarships/{item.slug}">{item.title}</a></h3><p class="provider">{item.provider}</p></div><div class="card-meta"><span><MapPin size={14}/>{item.country}</span><span><CalendarDays size={14}/>{dateLabel}</span></div><div class="card-bottom"><span>{item.fundingType}</span><a href="/scholarships/{item.slug}" aria-label="View {item.title}"><ArrowUpRight size={17}/></a></div></article>

